DELETE FROM `trait_definition_effect_points` WHERE `ID` IN (25238,25239,25240,25241);

DELETE FROM `trait_node_entry` WHERE `ID` IN (129593);

DELETE FROM `curve_point` WHERE `ID` IN (328044,328045,328046);

